import axios, { AxiosResponse } from "axios";
import { ReservedLinks, ReservedNames } from "../context";
import {
    AnnouncementConfig,
    CleverForms,
    DashboardLink,
    DBForm,
    DocumentSignature,
    FormLink,
    MyPay,
    NavigationRoute,
    SSLinkProp,
} from "../types";

const { REACT_APP_LOGIN_URL, REACT_APP_DEV_API, NODE_ENV } = process.env;

declare var window: any;

// axios.defaults.baseURL = 'http://localhost:3000';
axios.interceptors.request.use((config) => {
    let authHeader: any = {
        // "Cache-Control": "no-cache",
    };

    config.baseURL = NODE_ENV === "development" ? REACT_APP_DEV_API : undefined;
    config.withCredentials = true;
    config.headers = {
        ...config.headers,
        ...authHeader,
        "content-type": "application/json; charset=utf-8",
    };
    return config;
});

axios.interceptors.response.use(
    (res) => {
        switch (res.status) {
            case 401: // Unauthorize
                window.location.href = `${REACT_APP_LOGIN_URL}?redirectUrl=${window.location.href}`;
                break;
        }
        // Return data API Content
        return res;
    },
    (errors) => {
        if (errors.response.status === 401) {
            window.location.href = `${REACT_APP_LOGIN_URL}?redirectUrl=${window.location.href}`;
        }
        return Promise.reject(errors);
    }
);

interface IInitDataProps {
    appLinks: DashboardLink[];
    navLinks: NavigationRoute[];
    formLinks: FormLink[];
    activePage: string;
    dashboadProps: SSLinkProp;
}

export function fetchInitialData() {
    let initData = getInitialData();
    return {
        payslip: wrapPromise(initData),
    };
}

export function fetchMyPayData() {
    let data = getMyPayConfig();
    return {
        myPay: wrapPromise(data),
    };
}

export const getInitialData = async (): Promise<IInitDataProps> => {
    const navConfig = await getNavConfig();
    const { links, formLinks, activePage, appLinks, dashboadProps } = processUserNavLinks(navConfig);

    return {
        appLinks,
        navLinks: links,
        formLinks,
        activePage,
        dashboadProps,
    };
};

function processUserNavLinks(res: AxiosResponse<any, any>): {
    appLinks: DashboardLink[];
    links: NavigationRoute[];
    formLinks: FormLink[];
    activePage: string;
    dashboadProps: SSLinkProp;
} {
    const config: any = res.data;
    const appLinks: DashboardLink[] = config.Apps;
    const dashboadProps: SSLinkProp = {
        Id: config.Id,
        Url: config.Url,
    };
    let activePage = "",
        hasActive = false;
    // Changed to Config from Dashboard
    if (window.Affinity.app === "Config") {
        activePage = "Config";
    }

    const links: NavigationRoute[] = [
        {
            link: process.env.REACT_APP_DASHBOARD_URL as string,
            label: "Dashboard",
            icon: "dashboard",
            id: "Dashboard",
            enabled: true,
        },
    ];
    appLinks.forEach((app) => {
        if (app.Link) {
            const { Menu } = app.Link;
            let isCurrentPage = false;
            let subLinks: NavigationRoute[] = [];
            const linkValues = assignLinkValues(app.Link);
            if (linkValues.link) {
                isCurrentPage = setActiveMenu(linkValues.link, linkValues.id, false);
            }

            if (Menu.length) {
                Menu.forEach((m: any) => {
                    let isSubMenuActive = false;
                    const subLinkValues = assignLinkValues(m);

                    isSubMenuActive = setActiveMenu(subLinkValues.link, subLinkValues.id, true);
                    subLinks.push({
                        ...subLinkValues,
                        active: isSubMenuActive,
                    });
                    if (m.Url) {
                        let path = "";
                        try {
                            path = new URL(m.Url).pathname;
                        } catch (e) {
                            path = m.Url;
                        }
                        m.Show = ReservedLinks.includes(path) ? false : true;
                    } else m.Show = false;
                });
                // If current page is not coming from the sub-menu
                // Initialize isCurrentPage to false again
                if (subLinks.filter((sl) => sl.active).length === 0 && isCurrentPage) {
                    isCurrentPage = false;
                }
            }

            links.push({
                ...linkValues,
                subLinks,
                active: isCurrentPage,
            });

            if (isCurrentPage && !hasActive) {
                hasActive = true;
                activePage = linkValues.id;
            }

            app.ShowName = ReservedNames.includes(app.Name) ? false : true;
        }
    });

    const formLinks: any = config.Forms.map((m: any) => ({
        ...assignLinkValues(m),
    }));
    links.concat(formLinks);

    return {
        appLinks,
        links,
        formLinks: config.Forms,
        activePage,
        dashboadProps,
    };
}

